import{_ as t,o as a,c as r,a3 as i}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"MQTT local pour Zendure dans Home Assistant","description":"Configurer le MQTT local pour les anciens appareils Zendure.","frontmatter":{"title":"MQTT local pour Zendure dans Home Assistant","description":"Configurer le MQTT local pour les anciens appareils Zendure."},"headers":[],"relativePath":"fr/collection/zendure-ha/lokales-mqtt.md","filePath":"fr/collection/zendure-ha/lokales-mqtt.md","lastUpdated":1793126212000}'),l={name:"fr/collection/zendure-ha/lokales-mqtt.md"};function o(n,e,s,d,u,c){return a(),r("div",null,[...e[0]||(e[0]=[i('<p><a id="zendure-ha-lokales-mqtt"></a><a id="orientation-actuelle"></a></p><h1 id="lokales-mqtt" tabindex="-1">MQTT local <a class="header-anchor" href="#lokales-mqtt" aria-label="Permalink to &quot;MQTT local {#lokales-mqtt}&quot;">​</a></h1><p>Selon le wiki original, le MQTT local concerne principalement les anciens appareils Zendure :</p><ul><li>Hyper2000</li><li>Hub2000</li><li>Hub1200</li><li>Ace1500</li></ul><p>Les appareils plus récents, tels que le SolarFlow 800, le SolarFlow 800 Pro et le SolarFlow 2400, peuvent communiquer via <code>zenSDK</code> et ne nécessitent généralement pas de MQTT local.</p><h2 id="voraussetzungen" tabindex="-1">Exigences <a class="header-anchor" href="#voraussetzungen" aria-label="Permalink to &quot;Exigences {#voraussetzungen}&quot;">​</a></h2><ul><li>Courtier (broker) MQTT dans Home Assistant, par exemple Mosquitto</li><li>Intégration Bluetooth dans Home Assistant</li><li>L&#39;appareil Zendure doit être visible via Bluetooth</li><li>SSID du réseau Wi-Fi et mot de passe Wi-Fi</li><li>Nom d&#39;utilisateur et mot de passe MQTT</li></ul><div class="warning custom-block"><p class="custom-block-title">Adresse MQTT</p><p>Une adresse réseau réelle ou une adresse IP doit être utilisée comme adresse du serveur MQTT. Selon le wiki original, <code>core-mosquitto</code> ne constitue pas une adresse réseau valide pour les appareils Zendure.</p></div><h2 id="einrichtungsdaten" tabindex="-1">Données de configuration <a class="header-anchor" href="#einrichtungsdaten" aria-label="Permalink to &quot;Données de configuration {#einrichtungsdaten}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Champ</th><th>Exemple / Remarque</th></tr></thead><tbody><tr><td>Serveur MQTT</td><td>Adresse IP ou nom d&#39;hôte du courtier (broker)</td></tr><tr><td>Port MQTT</td><td>Généralement <code>1883</code></td></tr><tr><td>Utilisateur MQTT</td><td>Nom d&#39;utilisateur sur le courtier</td></tr><tr><td>Mot de passe MQTT</td><td>Mot de passe sur le courtier</td></tr><tr><td>SSID Wi-Fi</td><td>Réseau Wi-Fi auquel l&#39;appareil doit être connecté</td></tr><tr><td>Mot de passe Wi-Fi</td><td>Mot de passe de ce réseau Wi-Fi</td></tr></tbody></table><h2 id="verbindungsart-pro-gerat" tabindex="-1">Type de connexion par appareil <a class="header-anchor" href="#verbindungsart-pro-gerat" aria-label="Permalink to &quot;Type de connexion par appareil {#verbindungsart-pro-gerat}&quot;">​</a></h2><p>Pour les appareils pris en charge, il est possible de choisir le type de connexion pour chaque appareil :</p><ul><li><code>cloud</code></li><li><code>local</code></li><li>selon l&#39;appareil, également <code>zenSDK</code></li></ul><p>Lors du changement de type de connexion, l&#39;intégration tente de configurer le serveur MQTT sur l&#39;appareil via Bluetooth. L&#39;appareil peut redémarrer au cours de cette opération. Le processus peut prendre quelques secondes et génère ensuite une notification dans Home Assistant indiquant la réussite ou l&#39;échec de l&#39;opération.</p><h2 id="reset-verbindung" tabindex="-1">Réinitialisation de la connexion <a class="header-anchor" href="#reset-verbindung" aria-label="Permalink to &quot;Réinitialisation de la connexion {#reset-verbindung}&quot;">​</a></h2><p>Pour les appareils de l&#39;ancienne génération (« legacy »), l&#39;intégration met à disposition un bouton <code>Reset Verbindung</code>. Celui-ci peut être utilisé si la transition vers MQTT ne s&#39;est pas effectuée correctement.</p><p>Wiki original :</p><ul><li><a href="https://github.com/Zendure/Zendure-HA/wiki/Local-Mqtt-(Legacy-Devices)" target="_blank" rel="noreferrer">MQTT local (appareils de l&#39;ancienne génération)</a></li></ul>',18)])])}const m=t(l,[["render",o]]);export{h as __pageData,m as default};
